// Author: MiYu. Deferred live consumers for caster buffs, dispel, both shell modes and source autocast orders.
#include "session.h"
#include "setup.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=3)throw std::runtime_error("Usage: war3_caster_tests <data-root> <generated-caster-map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession s(jass::Module::compile(jass::Program::read(archives)),info);s.attachWorld(std::move(world));s.audioMuted(true);s.configure();PlayerSetup setup(info,s.config());s.applySetup(setup);s.startMain();auto& vm=s.runtime();
        auto check=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto real=[](float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));};auto number=[](jass::Real v){return std::bit_cast<float>(v.bits());};auto code=[&](const char* id){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(id)));};auto bounds=s.world()->bounds();auto x=bounds.minX.add(bounds.maxX).divide(jass::Real::fromInteger(2)),y=bounds.minY.add(bounds.maxY).divide(jass::Real::fromInteger(2));vm.invoke("FogEnable",std::array{vm.boolean(false)});vm.invoke("FogMaskEnable",std::array{vm.boolean(false)});
        auto create=[&](unsigned owner,const char* type,float offset){auto h=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),code(type),vm.real(x.add(real(offset))),vm.real(y),vm.real(real(0))});vm.invoke("SetUnitPathing",std::array{h,vm.boolean(false)});auto u=s.units().at(h.bits);u->healthRegen=u->manaRegen=0;u->acquireRange={};u->autocast.clear();u->maxLife=real(2000);u->life=u->maxLife;u->mana=u->maxMana=real(10000);s.stopUnit(h.bits);return h;};auto caster=create(0,"Hpal",0),friendUnit=create(0,"hfoo",100),enemy=create(1,"hfoo",150),opponent=create(1,"Hpal",200);auto c=s.units().at(caster.bits),f=s.units().at(friendUnit.bits),e=s.units().at(enemy.bits);auto add=[&](jass::Value u,const char* ability){check(vm.invoke("UnitAddAbility",std::array{u,code(ability)}).bits!=0,"Source ability add rejected");};for(auto id:{"Ahea","Aslo","Ainf","Ablo","Arej","Auhf","Acrs","Adis","Aadm","Aams","Aam2","A0CS"})add(caster,id);for(auto id:{"Ainf","Aslo","AHwe"})add(opponent,id);
        check(!s.castSpell(caster.bits,ObjectData::code("Ainf"),friendUnit.bits),"Training prerequisite was ignored");for(unsigned owner:{0u,1u})for(auto [type,level]:std::initializer_list<std::pair<const char*,int>>{{"Rhpt",2},{"Rost",2},{"Rune",1},{"Ruba",1},{"Resi",1},{"Redc",1}})vm.invoke("SetPlayerTechResearched",std::array{vm.handle("player",0x100000+owner),code(type),vm.integer(level)});
        auto reset=[&]{s.stopUnit(caster.bits);vm.invoke("UnitResetCooldown",std::array{caster});c->mana=c->maxMana;s.advance(1.5);};auto cast=[&](const char* id,jass::Value target){reset();check(s.castSpell(caster.bits,ObjectData::code(id),target.bits),"Manual caster order rejected");s.advance(.75);};
        f->life=real(100);cast("Ahea",friendUnit);check(std::abs(number(f->life)-125)<.01f && !s.castSpell(caster.bits,ObjectData::code("Ahea"),enemy.bits),"Heal amount or relationship differs");cast("Aslo",enemy);check(std::abs(e->spellMoveFactor()-.4f)<.001f && std::abs(e->spellAttackReduction()-.25f)<.001f,"Slow state not consumed");cast("Ainf",friendUnit);check(f->spellBonus(&UnitBuff::armor)==5 && std::abs(f->spellBonus(&UnitBuff::damageBonus)-.1f)<.001f && f->buffs.at(ObjectData::code("Binf")).positive,"Inner Fire modifiers missing");cast("Ablo",friendUnit);check(std::abs(f->spellBonus(&UnitBuff::attackBonus)-.4f)<.001f && std::abs(f->spellBonus(&UnitBuff::moveBonus)-.25f)<.001f && std::abs(f->displayScale()/f->scale-1.3f)<.001f,"Bloodlust speed or source scaling missing");cast("Acrs",enemy);check(std::abs(e->spellBonus(&UnitBuff::missChance)-.33f)<.001f,"Curse miss modifier missing");
        f->life=real(100);cast("Arej",friendUnit);s.advance(13);check(number(f->life)>=499.9f && !f->buffs.contains(ObjectData::code("Brej")),"Rejuvenation total or expiry differs");cast("Auhf",friendUnit);auto life=number(f->life);s.advance(2);check(number(f->life)<life-7.9f && f->spellBonus(&UnitBuff::attackBonus)>.74f,"Unholy Frenzy attack speed or periodic damage missing");reset();check(s.castSpellAt(caster.bits,ObjectData::code("Adis"),{f->x,f->y}),"Area Dispel rejected");s.advance(.75);check(f->buffs.empty() && e->buffs.empty() && f->spellBonus(&UnitBuff::armor)==0 && f->displayScale()==f->scale,"Area Dispel retained magical state");
        check(s.castSpell(opponent.bits,ObjectData::code("Ainf"),enemy.bits),"Enemy buff setup rejected");s.advance(1.5);cast("Aadm",enemy);check(!e->buffs.contains(ObjectData::code("Binf")),"Abolish did not remove enemy positive buff");check(s.castSpell(opponent.bits,ObjectData::code("Aslo"),friendUnit.bits),"Friendly debuff setup rejected");s.advance(1.5);cast("Aadm",friendUnit);check(!f->buffs.contains(ObjectData::code("Bslo")),"Abolish did not remove friendly negative buff");s.stopUnit(opponent.bits);check(s.castSpell(opponent.bits,ObjectData::code("AHwe")),"Dispel summon setup rejected");s.advance(1.5);std::uint32_t summon=0;for(auto& [id,u]:s.units())if(u->summoner==opponent.bits && number(u->life)>0){summon=id;u->acquireRange={};s.stopUnit(id);}check(summon!=0,"Real summoned unit missing");auto summoned=s.units().at(summon);life=number(summoned->life);cast("Aadm",vm.handle("unit",summon));check(life-number(summoned->life)>=299,"Abolish source summoned damage missing");
        cast("Aam2",friendUnit);check(f->buffs.contains(ObjectData::code("Bam2")) && f->buffs.at(ObjectData::code("Bam2")).shield==300,"Matrix source shield missing");life=number(f->life);s.damageUnit(opponent.bits,friendUnit.bits,200,0,14);check(number(f->life)==life && f->buffs.at(ObjectData::code("Bam2")).shield==100,"Matrix did not absorb spell damage");s.damageUnit(opponent.bits,friendUnit.bits,200,0,14);check(std::abs(number(f->life)-(life-100))<.01f && !f->buffs.contains(ObjectData::code("Bam2")),"Matrix overflow or retirement differs");cast("Aams",friendUnit);life=number(f->life);check(!s.damageUnit(opponent.bits,friendUnit.bits,100,0,14) && number(f->life)==life && !s.castSpell(opponent.bits,ObjectData::code("Aslo"),friendUnit.bits),"Full shell did not protect damage and targeting");s.damageUnit(opponent.bits,friendUnit.bits,10,1,4);check(number(f->life)<life,"Full shell blocked physical attack");reset();check(s.castSpellAt(caster.bits,ObjectData::code("Adis"),{f->x,f->y}),"Shell Dispel rejected");s.advance(.75);check(!f->buffs.contains(ObjectData::code("Bams")),"Shell was not dispellable");
        cast("A0CS",enemy);f->life=f->maxLife;life=number(f->life);check(s.attackUnit(enemy.bits,friendUnit.bits),"Cursed attack order rejected");s.advance(4);s.stopUnit(enemy.bits);check(number(f->life)==life,"Full curse did not cancel real weapon hits");
        reset();f->life=real(100);auto& heal=s.spellInfo(ObjectData::code("Ahea"),1);check(vm.invoke("IssueImmediateOrderById",std::array{caster,vm.integer(int(heal.orderOn))}).bits!=0 && c->autocast.at(ObjectData::code("Ahea")),"Autocast ID on order failed");s.advance(1.5);check(number(f->life)>=125,"Enabled autocast did not heal useful target");check(vm.invoke("IssueImmediateOrder",std::array{caster,vm.string("healoff")}).bits!=0,"Autocast string off order failed");s.advance(2);auto healed=number(f->life);s.advance(2);check(number(f->life)==healed,"Disabled autocast kept healing");s.stopUnit(caster.bits);check(s.attackUnit(caster.bits,enemy.bits),"Combat resume setup rejected");check(s.abilityAutocast(caster.bits,ObjectData::code("Ahea"),true),"Combat autocast enable failed");s.advance(3);check(s.abilityAutocast(caster.bits,ObjectData::code("Ahea"),false),"Combat autocast disable failed");s.advance(2);check(!c->cast && c->combat.target==enemy.bits,"Completed automatic cast lost prior attack command");
        add(caster,"AHhb");vm.invoke("SetUnitAbilityLevel",std::array{caster,code("AHhb"),vm.integer(3)});s.abilityCommands(caster.bits,0,true);if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS caster consumers: source states, dispel, summons, both shell modes, full curse, autocast orders and combat resumption\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
